__NUXT_JSONP__("/ar", (function(a,b,c,d,e){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002Flocalhost:8000",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:b,pageTitle:c,pageDescription:c,peopleChooseMli:{title:"ثلاثة أسباب تجعل الطلاب يختارون دراسة اللغة الإنجليزية في معهد مينتور",lists:[{image:"\u002Fimages\u002Fhome\u002Far\u002Fpeople-choose-mli-1.jpg",title:"هوليوود و ويستوود",description:"المواقع الإستراتيجية لمعاهدنا في الأماكن الأكثر شعبية في لوس أنجلوس, حيث يتعلم الطالب ويستمتع بالمعيشة في لوس انجلوس ",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Far\u002Fpeople-choose-mli-2.jpg",title:"الصباح، بعد الظهر ودروس المسائية",description:"خيارات الجدول و الكلاسات متعددة حيث لدينا دورات تبدأ في الصباح و أخرى بعد الظهر وكذلك لدينا دورات تبدأ في المساء",read_more:[a]},{image:"\u002Fimages\u002Fhome\u002Far\u002Fpeople-choose-mli-3.jpg",title:"$201\u002F1 ويك ~",description:"رسوم الدورات لدينا معقولة, يمكنك مقارنة أسعارنا مع المعاهد الأخرى, للمزيد من التفاصيل عن الرسوم الدراسية إضغط هنا ",read_more:[a]}]},highlyRated:"\u002Fimages\u002Fhome\u002Far\u002Fmli-highly-rated.jpg",courses:{title:"الدورات",lists:[{image:d,title:"ESL برنامج",subtitle:["برنامج أكاديمي عام و خيار مثالي لمن يرغب بتظوير لغتة الإنجليزية بشكل عام, حيث يحتوي على المهارات الأساسية لتعلم اللغة. يتكون هذا البرنامج من حصص لتطوير مهارة الاستماع و المحادثة و القراءة و الكتابة و تطوير المفردات و القواعد اللغوية."]},{image:e,title:"برنامج التوفل",subtitle:["برنامج التوفل يقدم حصص مكثقة لتطوير المهارات و الاستراتيجيات اللازمة لتحقيق الدرجة المطلوبة في اختبار التوفل بالانترنت (iBT) بأقسامه الأربعة. "]},{image:d,title:"Vacation ESL program (لطالب قصير المدى)",subtitle:["يتكون هذا البرنامج من دروس الاستماع \u002F التحدث والقراءة \u002F المفردات والقواعد \u002F الكتابة. \u003Cbr\u003Eنحن نقدم برنامج ESL لقضاء العطلات للطلاب الذين يرغبون في دراسة اللغة الإنجليزية لفترة قصيرة."]},{image:e,title:"IELTS™",subtitle:["\"أيلتس هو إختبار تم إعداده في بريطانيا و أستراليا لتقييم إجادة الطلاب للغة الإنجليزية. معظم الجامعات الأمريكية تقبل التفدم لها بدرجة أيلتس أو توفل, ويعتبر بعض الطلاب أن ايلتس هو الخيار الأسهل لمن يجد صعوبة في إجتياز التوفل. يتكون برنامج ايلتس من أربع أفسام: الإستماع, القراءة, الكتابة و تقييم التحدث. في هذا البرنامج يتعلم الطالب المهارات و الاستراتيجيات اللازمة لتحقيق الدرجة العالية في كل قسم.\""]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"برنامج المحادثة",subtitle:["برنامجنا يركز على تعزيز مهارات المحادثة باللغة الإنجليزية من خلال أنشطة شيقة وتعلم تفاعلي! في فصول المحادثة لدينا، سيستكشف الطلاب مجموعة واسعة من المفردات والعبارات والتعابير التي ستجعل محادثاتك تنبض بالحياة. امارس نطقك في فصل CMAR لدينا. من خلال مناقشات ممتعة وتمارين الأدوار وأنشطة العمل الجماعي، ستكتسب الثقة في التعبير عن نفسك والمشاركة في محادثات ذات مغزى. يقدم مدرسونا ذوو الخبرة بيئة تعلم داعمة، موجهينك في رحلة اكتشاف اللغة."]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"الأعمال + تويك",subtitle:["اختبار TOEIC® هو مؤشر على إجادة اللغة الإنجليزية في الأعمال التجارية وتستخدم من قبل مختلف الشركات والمنظمات في جميع أنحاء العالم. بالإضافة إلى دورة الأعمال القياسية، و TOEIC® هي دورة لإعداد الطلاب للنجاح في TOEIC® - ليزتينينغ و امتحان القراءة من خلال إدخال المفردات الأساسية واستكشاف استراتيجيات لتحقيق الدرجة المطلوبة. هذه الدورة مفيدة أيضا في تحسين مهارات الطلاب في اللغة الإنجليزية، مثل المفردات، والقراءة، والاستماع، و القواعد النحوية. من خلال تعلم استراتيجيات للعثورعلى الإجابات الصحيحة، والقدرة على تحقيق درجة عالية."]}]},schedule:"\u002Fimages\u002Fhome\u002Fen\u002Ffree_trial_banner-En.png",link:"\u002Far\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"الموقع \u002F الحرم الجامعي",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"معهد حي ويستوود ",subtitle:"فرعنا الأول في حي ويستوود, يقع غرب لوس أنجلوس, وهوي حي حيوي نشط حيث العديد من المعاهد و المؤسسات التعليمية هناك, يعتبر حي ويستوود منطقة سكنية آمنة وممتعة و شعبية للطلاب فيه العديد من المحلات التجارية و المطاعم و أماكن تستحق الزيارة, معهدنا يقع بجوار أحد المتاحف الشهيرة في لوس انجلوس",read_more:["\u003Ca href=\"\u002Far\u002Fwestwood\u002F\"\u003E» قرأ أكثر\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"معهد حي هوليوود ",subtitle:"فرعنا الآخر يقع في حي هوليوود بجوار المسرح الصيني الشهير, يعتبر حي هوليوود وجهة سياحية حيث هناك السينما الشهيرة والمطاعم الجيدة و المحلات التجارية.",read_more:["\u003Ca href=\"\u002Far\u002Fhollywood\u002F\"\u003E» قرأ أكثر\u003C\u002Fa\u003E"]}]},testimonials:{title:"شهادات الطلاب ",seemoreBtn:"اظهار المزيد",TestimonialLink:"\u002Far\u002Ftestimonials",readmoreBtn:"اقرأ المزيد"},dir:"\u002Fhome",path:"\u002Fhome\u002Far",extension:".json",createdAt:"2026-10-22T16:31:29.576Z",updatedAt:"2025-05-26T12:06:27.782Z"},lang:b}],fetch:{},mutations:void 0}}("\u003Ca href=\"\u002Far\u002Ffeature\u002F\"\u003E» اقرأ أكثر\u003C\u002Fa\u003E","ar","مدرسة اللغة الإنجليزية ممتازة فعالة من حيث التكلفة في لوس انجليس | Mentor Language Institute","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));